def test_removed_test_entry_purged_on_rerun(tmp_path):
    """A marker taken out of a file that runs again is reaped on that run."""
    root = _project(tmp_path)
    _run_pytest_with_plugin(root, """
        import pytest

        @pytest.mark.proof("feat", "PROOF-1", "RULE-1")
        def test_one():
            assert True

        @pytest.mark.proof("feat", "PROOF-2", "RULE-2")
        def test_two():
            assert True
    """)
    assert {e["id"] for e in _proofs(root, "feat")["proofs"]} == {"PROOF-1",
                                                                 "PROOF-2"}
    _run_pytest_with_plugin(root, """
        import pytest

        @pytest.mark.proof("feat", "PROOF-1", "RULE-1")
        def test_one():
            assert True
    """)
    assert {e["id"] for e in _proofs(root, "feat")["proofs"]} == {"PROOF-1"}

def test_three_features_keep_their_own_files(self, tmp_path):
        root = _project(tmp_path)
        for index, feature in enumerate(('alpha', 'beta', 'gamma'), start=1):
            _shell_run(root, 'tests/%s.test.sh' % feature, feature,
                       [('PROOF-%d' % index, 'RULE-1', 'pass', feature)])
        loaded = _read(root)
        assert sorted(loaded) == ['alpha', 'beta', 'gamma']
        for feature in loaded:
            assert len(loaded[feature]) == 1
